xml.Script:
        Colors[0] := '009600'; // Green
        Colors[1] := 'FF800A'; // Orange
        Colors[2] := '0000C8'; // Blue
        Colors[3] := 'C80000'; // Red
        clYellow := 'FFFF00';
        clWhite  := 'FFFFFF';

        R := 0.5;
        H := R;
        S2 := sqrt(2);

        for i := 0 to 39 do begin
            x[i] := R * cos(2 * Pi / 40 * i);
            y[i] := R * sin(2 * Pi / 40 * i);
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;
